//! 🧪️ Real complete native owners lend exact slots and close under their initiating Source.
use semio_framework_job_failure::*;
use semio_framework_io_control::{NativeSnapshotFailure,NativeSnapshotAllocationFailure};
use semio_framework_value::{ValueError,ValueRefusalKind,RetainedCloneGrant,RetainedCloneProgress,OriginalRetirementFailure,retirement::controlled::ControlledRetirement,native_encoding::{NativeEncodeAllocationOutcome,NativeEncodeEffectFailure}};
use semio_framework_value_native_owned::native_decoding::NativeDecodeAllocationOutcome;
use semio_framework_value_retained_clone::{NativeAllocationFailure,NativeAllocationRefusal,NativeAllocationRequest};
use OriginalDomainView as V;
fn error(name:&str)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,format!("{} 源",name))}
fn refusal(name:&str)->NativeAllocationRefusal{error(name).into()}
fn decode()->NativeDecodeAllocationOutcome{NativeDecodeAllocationOutcome{request:Some(NativeAllocationRequest{bytes:7,owned_bytes:13,next_owned_bytes:20,maximum_bytes:73}),admitted:false,primary:Some(error("decode primary")),quote_refusal:Some(refusal("decode quote")),extent_refusal:Some(error("decode extent")),settlement_refusal:Some(refusal("decode settlement")),actual:Some(11)}}
fn encode()->NativeEncodeAllocationOutcome{NativeEncodeAllocationOutcome{request:Some(NativeAllocationRequest{bytes:7,owned_bytes:13,next_owned_bytes:20,maximum_bytes:73}),admitted:true,primary:Some(error("encode primary")),forwarded_quote:Some(refusal("encode forwarded quote")),scoped_quote:Some(refusal("encode scoped quote")),extent_refusal:Some(error("encode extent")),forwarded_refusal:Some(refusal("encode forwarded refusal")),scoped_refusal:Some(refusal("encode scoped refusal")),actual:Some(11)}}
fn allocation()->NativeAllocationFailure{let mut a=NativeAllocationFailure::default();a.primary=Some(error("allocation primary"));a.admission=Some(error("admission"));a.forwarded_admission=Some(refusal("forwarded admission"));a.scoped_admission=Some(refusal("scoped admission"));a.forwarded_quote=Some(refusal("forwarded quote"));a.scoped_quote=Some(refusal("scoped quote"));a.forwarded_post=Some(refusal("forwarded post"));a.scoped_post=Some(refusal("scoped post"));a.forwarded_cancel=Some(refusal("forwarded cancel"));a.scoped_cancel=Some(refusal("scoped cancel"));a.receipt=Some(error("allocation receipt"));a.extent=Some(error("allocation extent"));a.progress.prior_admitted_bytes=Some(13);a.progress.requested_bytes=Some(7);a.progress.maximum_bytes=Some(73);a.progress.admitted_bytes=20;a.progress.actual_capacity_bytes=Some(11);a}
fn receiving()->OriginalReceivingPrimary{OriginalReceivingPrimary::from_fields(Some(error("primary")),Some(error("quote")),Some(error("allocation")),Some(error("work")),None,Some(OriginalRetirementFailure::from_causes(Some(error("retirement primary")),Some(error("retirement work")),Some(error("retirement receipt")),None)),Some(allocation()),Some(decode()),Some(error("receiving receipt")),RetainedCloneProgress{copied_items:7,copied_bytes:13,retained_capacity_bytes:20,released_bytes:73})}
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧪️fixtures/🔣️.json")).unwrap()}
fn keys(p:&impl OriginalDomainProjection,path:&[usize],expected:&serde_json::Value){let V::IntrinsicObject(count)=p.projection_view(path).unwrap()else{panic!("expected borrowed object")};assert_eq!(count,expected.as_array().unwrap().len());for(index,value)in expected.as_array().unwrap().iter().enumerate(){assert_eq!(p.projection_key(path,index).unwrap(),value.as_str().unwrap())}assert!(p.projection_key(path,count).is_err())}
fn text(p:&impl OriginalDomainProjection,path:&[usize])->(*const u8,usize){let V::IntrinsicText(value)=p.projection_view(path).unwrap()else{panic!("expected original text")};(value.as_ptr(),value.len())}
fn json(p:&impl OriginalDomainProjection,path:&mut Vec<usize>)->serde_json::Value{match p.projection_view(path).unwrap(){V::IntrinsicNull=>serde_json::Value::Null,V::IntrinsicBool(v)=>v.into(),V::IntrinsicNumber(semio_framework_value::Number::UInt(v))=>v.into(),V::IntrinsicText(v)=>v.into(),V::IntrinsicObject(n)=>{let mut m=serde_json::Map::new();for i in 0..n{let key=p.projection_key(path,i).unwrap().to_owned();path.push(i);let value=json(p,path);path.pop();m.insert(key,value);}serde_json::Value::Object(m)},_=>panic!("unexpected native failure projection kind")}}
fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:4096}}
/// 🏦️ Closes one controlled owner to terminal under one cancelled fixture caller, one funded effect-shaped step per turn.
fn close_all<T:semio_framework_value::retirement::RetireOwned>(owner:&mut ControlledRetirement<T>,operation:u64){
 use semio_framework_job_testing_caller::OriginalJobFixtureCaller;use semio_framework_job_context::{OperationId,Generation};
 let grant=stock();let mut caller=OriginalJobFixtureCaller::admit(OperationId(operation),Generation(7),grant,||Some(1000),1500,65536);caller.cancel().cancel_now();
 for _ in 0..100000{if owner.terminal_is_empty(){break}caller.turn(grant,|cx|{let body=grant.maximum_copy_bytes;semio_framework_job::close_original_effect_step(cx,owner.selected_demand(body)?,|effect|owner.step(body,effect))?;Ok(())}).unwrap();}
 assert!(owner.terminal_is_empty());caller.retire(grant);
}
#[test]
fn complete_receiving_borrows_original_slots_without_a_heap_mirror(){let f=fixture();let value=receiving();let pointers=[value.primary.as_ref().unwrap().message.as_ptr(),value.retirement_failure.as_ref().unwrap().primary().unwrap().message.as_ptr(),value.allocation_failure.as_ref().unwrap().forwarded_post.as_ref().unwrap().owned().unwrap().message.as_ptr(),value.native_allocation.as_ref().unwrap().settlement_refusal.as_ref().unwrap().owned().unwrap().message.as_ptr(),value.receipt_refusal.as_ref().unwrap().message.as_ptr()];let owner=OriginalNativeSnapshotFailure::from(NativeSnapshotFailure::from(value).with_receipt_refusal(error("outer receipt")).with_context_refusal(error("outer context")).with_work_post(error("outer work")).unwrap().with_settlement_refusal(error("outer settlement")).unwrap().with_allocation(NativeSnapshotAllocationFailure::Encode(encode())).unwrap());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{keys(&owner,&[],&f["keys"]["snapshot"]);let original=owner.original.receiving_primary().unwrap();assert!(matches!(project_original_receiving_primary(original,&[]).unwrap(),V::IntrinsicObject(9)));for(index,key)in f["keys"]["receiving"].as_array().unwrap().iter().enumerate(){assert_eq!(key_original_receiving_primary(original,&[],index).unwrap(),key.as_str().unwrap())}for(path,pointer)in[([0,1],pointers[0]),([7,1],pointers[4])]{assert!(matches!(project_original_receiving_primary(original,&path).unwrap(),V::IntrinsicText(message)if message.as_ptr()==pointer));}assert!(matches!(project_original_receiving_primary(original,&[5,6,1]).unwrap(),V::IntrinsicText(message)if message.as_ptr()==pointers[2]));keys(&owner,&[0],&f["keys"]["snapshotReceiving"]);keys(&owner,&[0,6],&f["keys"]["snapshotRetirement"]);keys(&owner,&[0,7],&f["keys"]["nativeAllocation"]);keys(&owner,&[0,7,12],&f["keys"]["allocationProgress"]);keys(&owner,&[0,8],&f["keys"]["decode"]);keys(&owner,&[1],&f["keys"]["encode"]);keys(&owner,&[1,1],&f["keys"]["request"]);assert_eq!([text(&owner,&[0,1,1]).0,text(&owner,&[0,6,0,1]).0,text(&owner,&[0,7,6,1]).0,text(&owner,&[0,8,6,1]).0,text(&owner,&[0,9,1]).0],pointers);assert!(matches!(owner.projection_view(&[2]).unwrap(),V::IntrinsicNull));assert!(owner.projection_view(&[0,12]).is_err());});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let wire=json(&owner,&mut Vec::new());let mut observe=|_|true;let mut encoder=semio_framework_value::NativeEncodeControl::new(1048576,&mut observe);let canonical=owner.original.to_value_controlled(&mut encoder).unwrap();drop(encoder);assert_eq!(wire,serde_json::to_value(&canonical).unwrap());let mut canonical=ControlledRetirement::retain(canonical);close_all(&mut canonical,9185);assert!(canonical.terminal_is_empty());assert_eq!(wire["cause"]["allocationFailure"]["forwardedPost"]["message"],"forwarded post 源");assert_eq!(wire["cause"]["nativeAllocation"]["actual"],11);assert_eq!(wire["cause"]["retirementFailure"]["primary"]["message"],"retirement primary 源");assert_eq!(wire["contextRefusal"]["message"],"outer context 源");let mut close=ControlledRetirement::retain(owner);close_all(&mut close,9186);assert!(close.terminal_is_empty());}
#[test]
fn encode_effect_and_independent_allocation_keep_their_exact_nested_causes(){let f=fixture();let effect=NativeEncodeEffectFailure{primary:Some(error("effect primary")),context:None,marker_failure:None,work_overrun:None,physical_receipt:None,invariant:Some(error("invariant")),physical_invariant:Some(error("physical invariant")),capacity_invariant:Some(error("capacity invariant")),work:Some(error("effect work")),local:Some(error("local")),physical:Some(error("physical")),allocation:Some(encode())};let pointer=effect.physical_invariant.as_ref().unwrap().message.as_ptr();let owner=OriginalNativeSnapshotFailure::from(NativeSnapshotFailure::from_encode_effect(effect,Default::default()).with_allocation(NativeSnapshotAllocationFailure::Decode(decode())).unwrap());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{keys(&owner,&[2],&f["keys"]["effect"]);keys(&owner,&[2,11],&f["keys"]["encode"]);keys(&owner,&[1],&f["keys"]["decode"]);assert_eq!(text(&owner,&[2,3,1]).0,pointer);assert!(matches!(owner.projection_view(&[0]).unwrap(),V::IntrinsicNull));});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let wire=json(&owner,&mut Vec::new());let mut observe=|_|true;let mut encoder=semio_framework_value::NativeEncodeControl::new(1048576,&mut observe);let canonical=owner.original.to_value_controlled(&mut encoder).unwrap();drop(encoder);assert_eq!(wire,serde_json::to_value(&canonical).unwrap());let mut canonical=ControlledRetirement::retain(canonical);close_all(&mut canonical,9185);assert!(canonical.terminal_is_empty());assert_eq!(wire["encodeEffect"]["physicalInvariant"]["message"],"physical invariant 源");assert_eq!(wire["encodeEffect"]["allocation"]["scopedRefusal"]["message"],"encode scoped refusal 源");let mut close=ControlledRetirement::retain(owner);close_all(&mut close,9186);assert!(close.terminal_is_empty());}
#[test]
fn native_snapshot_domain_custody_uses_the_same_actual_source_and_preserves_denied_donor(){use semio_framework_job_testing_caller::OriginalJobFixtureCaller;use semio_framework_job_context::{OperationId,Generation};let grant=stock();let mut caller=OriginalJobFixtureCaller::admit(OperationId(9181),Generation(7),grant,||Some(1000),1500,65536);let mut foreign=OriginalJobFixtureCaller::admit(OperationId(9181),Generation(7),grant,||Some(1000),1500,65536);let mut owner=Some(OriginalNativeSnapshotFailure::from(NativeSnapshotFailure::from(receiving())));let pointer=owner.as_ref().unwrap().original.message().as_ptr();let mut reservation=OriginalDomainReservation::new();caller.turn(grant,|cx|{assert!(reservation.prepare(cx)?);Ok(())}).unwrap();caller.turn(RetainedCloneGrant{maximum_copy_bytes:0,..grant},|cx|{assert!(!reservation.capture_original(cx,||owner.take().unwrap())?);Ok(())}).unwrap();assert_eq!(owner.as_ref().unwrap().original.message().as_ptr(),pointer);caller.turn(grant,|cx|{assert!(reservation.capture_original(cx,||owner.take().unwrap())?);Ok(())}).unwrap();assert!(owner.is_none());let allocation=reservation.allocation_identity();assert!(foreign.turn(grant,|cx|admit_original_domain_failure(&mut reservation,cx)).is_err());assert_eq!(reservation.allocation_identity(),allocation);let error=caller.turn(grant,|cx|admit_original_domain_failure(&mut reservation,cx)).unwrap().unwrap();assert_eq!(error.primary_domain().unwrap().message().as_ptr(),pointer);let mut close=ControlledRetirement::retain(error);for _ in 0..100000{if close.terminal_is_empty(){break}caller.turn(grant,|cx|{semio_framework_job::close_original_effect_step(cx,close.selected_demand(grant.maximum_copy_bytes)?,|effect|close.step(grant.maximum_copy_bytes,effect))?;Ok(())}).unwrap();}assert!(close.terminal_is_empty());caller.retire(grant);foreign.retire(grant);}
